import * as React from "react";
import { cx } from "./cx";

export interface DrawerProps extends Omit<React.DialogHTMLAttributes<HTMLDialogElement>, "open"> {
  open: boolean;
  onClose?: () => void;
}

/**
 * A native <dialog> from the bottom edge. The platform provides the
 * focus trap, Escape, and the backdrop.
 */
export function Drawer({ open, onClose, className, children, ...props }: DrawerProps) {
  const ref = React.useRef<HTMLDialogElement>(null);

  React.useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) dialog.showModal();
    else if (!open && dialog.open) dialog.close();
  }, [open]);

  return (
    <dialog
      ref={ref}
      className={cx("rs-drawer", className)}
      onClose={() => onClose?.()}
      {...props}
    >
      {children}
    </dialog>
  );
}

export function DrawerTitle({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={cx("rs-drawer-title", className)} {...props} />;
}

export function DrawerBody({ className, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p className={cx("rs-drawer-body", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Drawer: a native <dialog> from the bottom edge. No shadow. ── */
dialog.rs-drawer{position:fixed;inset:auto 0 0 0;margin:0;width:100%;max-width:none;height:auto;max-height:85dvh;border:none;border-top:1px solid var(--divider);border-radius:var(--radius-sm) var(--radius-sm) 0 0;padding:24px 20px;background:var(--bg);color:var(--text);box-shadow:none}
dialog.rs-drawer::backdrop{background:rgba(0,0,0,0.25)}
.rs-drawer-title{display:block;font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--text);margin-bottom:6px}
.rs-drawer-body{font-size:13.5px;line-height:1.6;letter-spacing:-.01em;color:var(--text-secondary);margin:0}
